<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount,nextTick} from 'vue'
import {useRoute,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {ElMessageBox} from 'element-plus'
import 'element-plus/es/components/message-box/style/css'
import {practiceState,practiceHistory,readingAttempt,startAttempt,saveAttemptChoice,submitAttemptChoice,type PracticeState,type ReadingAttempt,type AttemptSummary} from '@/api/attempts'
import {getAccessToken,getGeneration,onRemoteIdentityChange} from '@/auth/token-session'
import {useAuthStore} from '@/stores/auth'
import {useAuthDialogStore} from '@/stores/auth-dialog'
import {ApiError} from '@/api/client'
import {errorMessage} from '@/api/identity'
const emit=defineEmits<{completed:[]}>()
const props=defineProps<{article:string;version:string}>(),auth=useAuthStore(),login=useAuthDialogStore(),route=useRoute()
const state=ref<PracticeState>(),attempt=ref<ReadingAttempt>(),loading=ref(false),busy=ref(false),loadError=ref(''),error=ref(''),notice=ref(''),index=ref(0),choice=ref(''),lastAction=ref<'draft'|'submit'|'start'>('draft'),conflict=ref(false),sessionStale=ref(false),legend=ref<HTMLLegendElement>()
const history=ref<AttemptSummary[]>([]),historyOpen=ref(false),historyBusy=ref(false),historyError=ref(''),historyPage=ref(1),historyTotal=ref(0)
const question=computed(()=>attempt.value?.quiz.questions[index.value]),answer=computed(()=>attempt.value?.answers.find(a=>a.questionId===question.value?.id)),pending=computed(()=>!!question.value&&!answer.value?.submittedChoice&&choice.value!==(answer.value?.draftChoice??''))
const types:Record<string,string>={MAIN_IDEA:'主旨大意',DETAIL:'事实细节',INFERENCE:'推理判断',VOCABULARY:'词义猜测',ATTITUDE:'作者态度'}
let epoch=0,historySequence=0,disposed=false,controller:AbortController|undefined,historyController:AbortController|undefined,startId='',reauth=false,owner=auth.user?.id
function valid(ticket:number,identity:number){return !disposed&&ticket===epoch&&identity===getGeneration()&&owner===auth.user?.id}
function clear(){epoch++;historySequence++;controller?.abort();historyController?.abort();state.value=undefined;attempt.value=undefined;choice.value='';index.value=0;loading.value=false;busy.value=false;error.value='';loadError.value='';notice.value='';conflict.value=false;sessionStale.value=false;history.value=[];historyOpen.value=false;historyTotal.value=0;historyPage.value=1;historyBusy.value=false;historyError.value='';startId='';reauth=false}
function settle(ticket:number,identity:number){if(disposed||ticket!==epoch)return;busy.value=false;loading.value=false;if(identity!==getGeneration()){sessionStale.value=true;error.value='登录状态已失效，当前选择仍保留，请重新验证登录。';return}if(historyOpen.value)void loadHistory()}
function apply(data:ReadingAttempt,keepIndex=false){const wasCompleted=attempt.value?.status==='COMPLETED'&&attempt.value.id===data.id;if(data.status==='COMPLETED'&&!wasCompleted)emit('completed');const old=attempt.value?.id;attempt.value=data;index.value=keepIndex&&old===data.id?Math.min(index.value,data.quiz.questions.length-1):Math.max(0,data.quiz.questions.findIndex(q=>!data.answers.find(a=>a.questionId===q.id)?.submittedChoice));if(data.status==='COMPLETED'&&(!keepIndex||old!==data.id))index.value=data.quiz.questions.length-1;choice.value=answer.value?.draftChoice??answer.value?.submittedChoice??'';if(state.value){if(!state.value.current||data.id===state.value.current.id||data.status==='IN_PROGRESS')state.value.current=data;if(data.status==='COMPLETED'){state.value.first??=data;if(!state.value.latest||data.attemptNo>=state.value.latest.attemptNo)state.value.latest=data}}}
async function load(){clear();owner=auth.user?.id;if(!owner)return;const ticket=epoch,identity=getGeneration();controller=new AbortController();loading.value=true;try{const data=await practiceState(props.article,props.version,controller.signal);if(!valid(ticket,identity))return;state.value=data;if(data.current)apply(data.current)}catch(e){if(valid(ticket,identity))loadError.value=errorMessage(e)}finally{settle(ticket,identity)}}
async function leave(){if(busy.value)return false;if(!pending.value)return true;try{await ElMessageBox.confirm('当前选择尚未保存，离开会丢失这次选择。','离开练习',{confirmButtonText:'放弃本地选择',cancelButtonText:'继续练习',autofocus:false});return true}catch{return false}}
function authenticate(){reauth=true;login.switchMode('login');login.request(route.fullPath)}
watch(()=>login.open,open=>{if(!open&&reauth&&getAccessToken()&&owner===auth.user?.id){reauth=false;sessionStale.value=false;error.value='';notice.value='登录已恢复，请继续当前操作。';if(!state.value)void load()}})
async function start(redo=false){if(busy.value||sessionStale.value||!state.value?.published)return;const ticket=epoch,identity=getGeneration();busy.value=true;lastAction.value='start';try{if(redo){try{await ElMessageBox.confirm('会保留原有成绩，并按当前已发布题组开始一轮练习。','重新练习',{confirmButtonText:'确认重做',cancelButtonText:'取消',autofocus:false})}catch{return}}if(!valid(ticket,identity))return;error.value='';notice.value='';conflict.value=false;startId||=crypto.randomUUID();controller=new AbortController();const data=await startAttempt(state.value.published.id,state.value.published.versionId,startId,controller.signal,()=>valid(ticket,identity));if(!valid(ticket,identity))return;startId='';apply(data);if(historyOpen.value)void loadHistory()}catch(e){if(valid(ticket,identity)){error.value=errorMessage(e);conflict.value=e instanceof ApiError&&['QUIZ_CHANGED','QUIZ_UNAVAILABLE'].includes(e.code??'')}}finally{settle(ticket,identity)}}
async function write(submit:boolean){if(busy.value||sessionStale.value||!attempt.value||!question.value||answer.value?.submittedChoice||!choice.value)return false;const ticket=epoch,identity=getGeneration();busy.value=true;error.value='';notice.value='';conflict.value=false;lastAction.value=submit?'submit':'draft';controller=new AbortController();try{const data=await (submit?submitAttemptChoice:saveAttemptChoice)(attempt.value.id,question.value.id,choice.value,attempt.value.lockVersion,controller.signal,()=>valid(ticket,identity));if(!valid(ticket,identity))return false;apply(data,true);if(!submit)notice.value='选项已保存';if(submit&&historyOpen.value)void loadHistory();return true}catch(e){if(valid(ticket,identity)){error.value=errorMessage(e);conflict.value=e instanceof ApiError&&e.code==='ATTEMPT_CONFLICT'}return false}finally{settle(ticket,identity)}}
async function latest(){if(busy.value||!attempt.value||sessionStale.value)return;const ticket=epoch,identity=getGeneration(),local=choice.value,qid=question.value?.id;busy.value=true;controller=new AbortController();try{const data=await readingAttempt(attempt.value.id,controller.signal);if(!valid(ticket,identity))return;apply(data,true);if(question.value?.id===qid&&!answer.value?.submittedChoice){choice.value=local;notice.value='已加载最新记录，当前选择仍保留，请确认后再保存或提交。'}else notice.value=local&&local!==answer.value?.submittedChoice?`另一页面已提交本题；你的本地选择 ${local} 未提交。`:'已加载最新练习记录。';error.value='';conflict.value=false}catch(e){if(valid(ticket,identity))error.value=errorMessage(e)}finally{settle(ticket,identity)}}
async function move(target:number){if(busy.value||!attempt.value||target<0||target>=attempt.value.quiz.questions.length)return;if(pending.value&&!await write(false))return;index.value=target;choice.value=answer.value?.draftChoice??answer.value?.submittedChoice??'';error.value='';notice.value='';void nextTick(()=>legend.value?.focus())}
async function loadHistory(page=historyPage.value){if(busy.value||sessionStale.value)return;const ticket=epoch,identity=getGeneration(),sequence=++historySequence;historyController?.abort();historyController=new AbortController();historyBusy.value=true;historyError.value='';const current=()=>valid(ticket,identity)&&sequence===historySequence;try{const data=await practiceHistory(props.article,props.version,page,historyController.signal);if(current()){history.value=data.items;historyTotal.value=data.total;historyPage.value=page;historyError.value=''}}catch(e){if(current()&&!(e instanceof DOMException&&e.name==='AbortError'))historyError.value=errorMessage(e)}finally{if(!disposed&&ticket===epoch&&sequence===historySequence){historyBusy.value=false;if(identity!==getGeneration()){sessionStale.value=true;historyError.value='登录状态已失效，请重新验证登录。'}}}}
async function publication(){if(busy.value||sessionStale.value)return;const ticket=epoch,identity=getGeneration();busy.value=true;controller=new AbortController();try{const data=await practiceState(props.article,props.version,controller.signal);if(!valid(ticket,identity))return;state.value=data;if(!attempt.value&&data.current)apply(data.current);error.value='';conflict.value=false;notice.value='已加载当前题组，原轮次和选择仍保留。'}catch(e){if(valid(ticket,identity))error.value=errorMessage(e)}finally{settle(ticket,identity)}}
async function view(id:string){const ticket=epoch,identity=getGeneration();if(busy.value||sessionStale.value||!await leave()||!valid(ticket,identity))return;busy.value=true;controller=new AbortController();try{const data=await readingAttempt(id,controller.signal);if(valid(ticket,identity)){apply(data);error.value='';notice.value='正在查看该轮保存的题目与记录。'}}catch(e){if(valid(ticket,identity))error.value=errorMessage(e)}finally{settle(ticket,identity)}}
function historyToggle(event:Event){historyOpen.value=(event.target as HTMLDetailsElement).open;if(historyOpen.value)void loadHistory()}
function unloading(event:BeforeUnloadEvent){if(pending.value){event.preventDefault();event.returnValue=''}}
window.addEventListener('beforeunload',unloading)
const unsubscribe=onRemoteIdentityChange(()=>{clear();loadError.value='账户状态已变化，请重新加载练习。'})
watch(()=>auth.user?.id,(value,previous)=>{if(previous&&value!==previous){clear();loadError.value='账户状态已变化，请重新加载练习。'}},{flush:'sync'})
watch(()=>[props.article,props.version],load,{immediate:true});onBeforeRouteLeave(leave);onBeforeRouteUpdate(leave);onBeforeUnmount(()=>{disposed=true;clear();unsubscribe();window.removeEventListener('beforeunload',unloading)})
</script>
<template><details class="article-quiz-panel account-quiz-panel"><summary><span>阅读理解</span><small>{{ loading?'正在加载':attempt?`第${attempt.attemptNo}轮`:state?.published?`${state.published.questions.length}题`:'练习' }}</small></summary><div class="article-quiz-content"><p class="reader-rail-note">选项保存到当前账号；提交后显示解析。重新练习保留原成绩；读完文章并完成全部配套练习后自动打卡，同篇只计一次。</p><p v-if="loading" role="status">正在恢复练习…</p><div v-if="sessionStale" class="reading-notice" role="alert"><p>{{ error||historyError }}</p><button class="button-primary" type="button" @click="authenticate">重新验证登录</button></div><div v-if="loadError" role="alert"><p>{{ loadError }}</p><button class="button-secondary" type="button" @click="load">重试加载练习</button></div><template v-if="!loading&&!loadError&&state"><p v-if="state.first" class="quiz-first-score">首次成绩：{{ state.first.correctCount }} / {{ state.first.total }}</p><p v-if="!state.published" class="reader-rail-note">本篇暂未发布阅读题，或题组已下架；已有轮次与记录保留，仍可正常阅读。</p><template v-if="!attempt&&state.published"><p>{{ state.published.questions.length }} 道四选一题，逐题提交。</p><button class="button-primary" :disabled="busy||sessionStale" @click="start()">{{ busy?'正在开始…':'开始练习' }}</button></template><template v-if="question&&attempt"><p class="quiz-position">第 {{ index+1 }} / {{ attempt.total }} 题 · {{ types[question.type] }} · 第 {{ attempt.attemptNo }} 轮</p><p v-if="state.published&&attempt.quizVersionId!==state.published.versionId" class="reader-rail-note">题组已更新，本轮继续使用开始时的题目。</p><form @submit.prevent="write(true)"><fieldset :disabled="busy||sessionStale||!!answer?.submittedChoice"><legend ref="legend" tabindex="-1">{{ question.stem }}</legend><label v-for="(option,i) in question.options" :key="i" class="quiz-choice" :class="{selected:choice==='ABCD'[i]}"><input v-model="choice" type="radio" :name="`attempt-${attempt.id}-${question.id}`" :value="'ABCD'[i]" @change="write(false)"><span>{{ 'ABCD'[i] }}. {{ option }}</span></label></fieldset><p v-if="notice" role="status" class="reader-local-message">{{ notice }}</p><div v-if="answer?.submittedChoice" class="quiz-feedback" role="status"><strong>{{ answer.correct?'回答正确':'再看一下原文' }} · 正确答案：{{ answer.correctOption }}</strong><p>{{ answer.explanation }}</p><p v-if="attempt.status==='COMPLETED'">本次正确 {{ attempt.correctCount }} / {{ attempt.total }}（{{ Math.round((attempt.correctCount??0)/attempt.total*100) }}%）</p></div><div class="reading-actions"><button v-if="!answer?.submittedChoice" class="button-primary" :disabled="busy||sessionStale||!choice">{{ busy?'正在保存…':error&&lastAction==='submit'?'重试提交':'提交答案' }}</button><button v-if="pending&&!error&&!answer?.submittedChoice" type="button" class="button-secondary" :disabled="busy||sessionStale" @click="write(false)">保存当前选项</button><button v-if="index>0" type="button" class="button-secondary" :disabled="busy||sessionStale" @click="move(index-1)">上一题</button><button v-if="answer?.submittedChoice&&index<attempt.total-1" type="button" class="button-secondary" :disabled="busy||sessionStale" @click="move(index+1)">下一题</button><button v-if="attempt.status==='COMPLETED'&&state.published&&state.current?.status!=='IN_PROGRESS'" type="button" class="button-secondary" :disabled="busy||sessionStale" @click="start(true)">重新练习</button><button v-if="state.current?.status==='IN_PROGRESS'&&state.current.id!==attempt.id" type="button" class="button-secondary" :disabled="busy||sessionStale" @click="view(state.current!.id)">回到进行中的练习</button></div></form></template><div v-if="error&&!sessionStale" role="alert" class="auth-field-error"><p>{{ error }}</p><button v-if="conflict&&lastAction==='start'" type="button" class="button-secondary" :disabled="busy" @click="publication">加载当前题组并保留记录</button><button v-else-if="conflict&&attempt" type="button" class="button-secondary" :disabled="busy" @click="latest">加载最新练习并保留选择</button><button v-else-if="conflict" type="button" class="button-secondary" :disabled="busy" @click="load">加载当前题组</button><button v-else-if="lastAction==='draft'&&pending" type="button" class="button-secondary" :disabled="busy" @click="write(false)">重试保存选项</button><button v-else-if="lastAction==='start'" type="button" class="button-secondary" :disabled="busy" @click="start()">重试开始练习</button></div><details class="quiz-attempt-history" @toggle="historyToggle"><summary>练习记录</summary><p v-if="historyBusy" role="status">正在加载记录…</p><div v-else-if="historyError" role="alert"><p>{{ historyError }}</p><button class="button-secondary" :disabled="busy||sessionStale" @click="loadHistory()">重试练习记录</button></div><p v-else-if="!history.length" class="reader-rail-note">还没有练习记录。</p><ol v-else><li v-for="item in history" :key="item.id"><span>第 {{ item.attemptNo }} 轮 · {{ item.status==='COMPLETED'?`${item.correctCount} / ${item.total}`:'进行中' }}</span><button class="text-button" type="button" :disabled="busy||sessionStale" @click="view(item.id)">查看第{{ item.attemptNo }}轮</button></li></ol><div v-if="historyTotal>6" class="reading-actions"><button class="button-secondary" :disabled="historyBusy||busy||historyPage<=1||sessionStale" @click="loadHistory(historyPage-1)">上一页记录</button><span>第 {{ historyPage }} 页</span><button class="button-secondary" :disabled="historyBusy||busy||historyPage*6>=historyTotal||sessionStale" @click="loadHistory(historyPage+1)">下一页记录</button></div></details></template></div></details></template>
